#!/usr/bin/env bash
# Generated by wizard.sh for machine vps2.
# Run: sudo ./install.sh [--dry-run] [--force] [--step ID]
#   --step ID  only one step: NN for common/NN-*.sh (03-ssh lives in 03-ufw.sh), NN-id for a service
# Any other argument is rejected: this runs as root.
set -Eeuo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"
# Steps read node.env and secrets.env from here.
export HOMELAB_NODE_DIR=$PWD
IDS=(00 01 02 03 04 10 12-node-agent 30-postgresql 33-redis 39-postgres-exporter 90)
declare -A ALIASES=(["03-ssh"]=03)
STEPS=(
  ../common/00-preflight.sh
  ../common/01-base.sh
  ../common/02-wireguard.sh
  ../common/03-ufw.sh
  ../common/04-ca-trust.sh
  ../common/10-docker.sh
  services/node-agent/install.sh
  services/postgresql/install.sh
  services/redis/install.sh
  services/postgres-exporter/install.sh
  ../common/90-verify.sh
)
only='' args=()
while (($#)); do
  case $1 in
    --dry-run | --force)
      args+=("$1")
      shift
      ;;
    --step)
      if [[ -n $only || ! ${2:-} =~ ^[0-9]{2}(-[a-z0-9]+)*$ ]]; then
        echo "--step takes one step id, one of: ${IDS[*]} ${!ALIASES[*]}" >&2
        exit 2
      fi
      only=$2
      shift 2
      ;;
    *)
      echo "unknown argument (allowed: --dry-run, --force, --step ID)" >&2
      exit 2
      ;;
  esac
done
[[ -n $only && -n ${ALIASES[$only]-} ]] && only=${ALIASES[$only]}
selected=()
for i in "${!STEPS[@]}"; do
  if [[ -z $only || ${IDS[i]} == "$only" ]]; then selected+=("${STEPS[i]}"); fi
done
((${#selected[@]})) || {
  echo "unknown step: $only (steps: ${IDS[*]})" >&2
  exit 2
}
for f in "${selected[@]}"; do
  [[ -f $f ]] || {
    echo "missing install step: $f" >&2
    exit 1
  }
done
for f in "${selected[@]}"; do bash "$f" "${args[@]}"; done
